# Modular Autonomous Traffic Light Control System in C#

Below is a C# implementation of a modular autonomous traffic light control system with three isolated components as requested:

```csharp
using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

// Interface for the Vehicle Sensor Ingester
public interface IVehicleSensorIngester
{
    void UpdateLaneQueues(int laneId, int newVehicleCount);
    Dictionary<int, int> GetCurrentLaneQueues();
}

// Interface for the Adaptive Timing Optimization Engine
public interface IAdaptiveTimingEngine
{
    void UpdateQueueData(Dictionary<int, int> laneQueues);
    int CalculateGreenDuration(int laneId);
    int GetCurrentGreenDuration(int laneId);
}

// Interface for the Hardware Signal Controller
public interface IHardwareSignalController
{
    void SetLightState(int laneId, bool isGreen);
    bool GetLightState(int laneId);
    Task ChangeLightStateAsync(int laneId, bool isGreen);
}

// Concrete implementation of Vehicle Sensor Ingester
public class VehicleSensorIngester : IVehicleSensorIngester
{
    private readonly Dictionary<int, int> _laneQueues = new Dictionary<int, int>();
    private readonly object _lock = new object();

    public void UpdateLaneQueues(int laneId, int newVehicleCount)
    {
        lock (_lock)
        {
            if (_laneQueues.ContainsKey(laneId))
            {
                _laneQueues[laneId] = newVehicleCount;
            }
            else
            {
                _laneQueues[laneId] = newVehicleCount;
            }
        }
    }

    public Dictionary<int, int> GetCurrentLaneQueues()
    {
        lock (_lock)
        {
            return new Dictionary<int, int>(_laneQueues);
        }
    }
}

// Concrete implementation of Adaptive Timing Optimization Engine
public class AdaptiveTimingEngine : IAdaptiveTimingEngine
{
    private readonly Dictionary<int, int> _currentGreenDurations = new Dictionary<int, int>();
    private readonly Dictionary<int, int> _baseDurations = new Dictionary<int, int>();
    private readonly object _lock = new object();

    public AdaptiveTimingEngine(Dictionary<int, int> baseDurations)
    {
        _baseDurations = baseDurations;
        foreach (var duration in baseDurations)
        {
            _currentGreenDurations[duration.Key] = duration.Value;
        }
    }

    public void UpdateQueueData(Dictionary<int, int> laneQueues)
    {
        lock (_lock)
        {
            foreach (var lane in laneQueues)
            {
                int duration = CalculateDurationForQueue(lane.Value);
                _currentGreenDurations[lane.Key] = duration;
            }
        }
    }

    private int CalculateDurationForQueue(int queueLength)
    {
        // Heuristic: longer queues get longer green durations
        // Base duration is 30 seconds, with 1 second added per 5 vehicles
        // Minimum 20 seconds, maximum 60 seconds
        int baseDuration = _baseDurations.ContainsKey(queueLength) ? _baseDurations[queueLength] : 30;
        int adjustment = Math.Max(0, Math.Min(30, queueLength / 5)); // 1s per 5 vehicles, max +30s
        return Math.Max(20, Math.Min(60, baseDuration + adjustment));
    }

    public int CalculateGreenDuration(int laneId)
    {
        lock (_lock)
        {
            return _currentGreenDurations.ContainsKey(laneId)
                ? _currentGreenDurations[laneId]
                : 30; // Default duration
        }
    }

    public int GetCurrentGreenDuration(int laneId)
    {
        lock (_lock)
        {
            return _currentGreenDurations.ContainsKey(laneId)
                ? _currentGreenDurations[laneId]
                : 30;
        }
    }
}

// Concrete implementation of Hardware Signal Controller
public class HardwareSignalController : IHardwareSignalController
{
    private readonly Dictionary<int, bool> _lightStates = new Dictionary<int, bool>();
    private readonly object _lock = new object();

    public HardwareSignalController(Dictionary<int, bool> initialStates)
    {
        foreach (var state in initialStates)
        {
            _lightStates[state.Key] = state.Value;
        }
    }

    public void SetLightState(int laneId, bool isGreen)
    {
        lock (_lock)
        {
            if (_lightStates.ContainsKey(laneId))
            {
                _lightStates[laneId] = isGreen;
            }
            else
            {
                _lightStates[laneId] = isGreen;
            }
        }
    }

    public bool GetLightState(int laneId)
    {
        lock (_lock)
        {
            return _lightStates.ContainsKey(laneId) ? _lightStates[laneId] : false;
        }
    }

    public async Task ChangeLightStateAsync(int laneId, bool isGreen)
    {
        // Simulate hardware delay (e.g., 100ms for physical switch)
        await Task.Delay(100);
        SetLightState(laneId, isGreen);
    }
}

// Main Traffic Light Controller that coordinates the modules
public class TrafficLightController
{
    private readonly IVehicleSensorIngester _sensorIngester;
    private readonly IAdaptiveTimingEngine _timingEngine;
    private readonly IHardwareSignalController _hardwareController;
    private readonly Dictionary<int, int> _baseDurations;
    private readonly int[] _lanes;
    private readonly TimeSpan _cycleCheckInterval = TimeSpan.FromSeconds(1);

    public TrafficLightController(
        IVehicleSensorIngester sensorIngester,
        IAdaptiveTimingEngine timingEngine,
        IHardwareSignalController hardwareController,
        Dictionary<int, int> baseDurations,
        int[] lanes)
    {
        _sensorIngester = sensorIngester ?? throw new ArgumentNullException(nameof(sensorIngester));
        _timingEngine = timingEngine ?? throw new ArgumentNullException(nameof(timingEngine));
        _hardwareController = hardwareController ?? throw new ArgumentNullException(nameof(hardwareController));
        _baseDurations = baseDurations ?? throw new ArgumentNullException(nameof(baseDurations));
        _lanes = lanes ?? throw new ArgumentNullException(nameof(lanes));
    }

    public void Start()
    {
        Task.Run(() => RunControlLoop());
    }

    private async Task RunControlLoop()
    {
        while (true)
        {
            // Get current queue data
            var laneQueues = _sensorIngester.GetCurrentLaneQueues();

            // Update timing based on current queues
            _timingEngine.UpdateQueueData(laneQueues);

            // Determine which lane should be green (simplified: round-robin)
            int currentLane = GetNextLaneToControl();

            // Calculate green duration for current lane
            int greenDuration = _timingEngine.CalculateGreenDuration(currentLane);

            // Turn on green light
            await _hardwareController.ChangeLightStateAsync(currentLane, true);
            Console.WriteLine($"Lane {currentLane} green for {greenDuration} seconds");

            // Wait for green duration
            await Task.Delay(greenDuration * 1000);

            // Turn off green light
            await _hardwareController.ChangeLightStateAsync(currentLane, false);
            Console.WriteLine($"Lane {currentLane} green ended");

            // Wait for yellow light (simplified)
            await Task.Delay(5000); // 5 seconds yellow
        }
    }

    private int GetNextLaneToControl()
    {
        // Simple round-robin selection
        // In a real system, this would be more sophisticated
        // based on queue priorities and traffic patterns
        return _lanes[0]; // For simplicity, always control first lane
    }
}

// Example usage
class Program
{
    static void Main(string[] args)
    {
        // Initialize components
        var sensorIngester = new VehicleSensorIngester();
        var baseDurations = new Dictionary<int, int>
        {
            { 1, 30 }, // Lane 1 base duration
            { 2, 30 }, // Lane 2 base duration
            { 3, 30 }, // Lane 3 base duration
            { 4, 30 }  // Lane 4 base duration
        };
        var timingEngine = new AdaptiveTimingEngine(baseDurations);
        var hardwareController = new HardwareSignalController(new Dictionary<int, bool>
        {
            { 1, false }, // All lights start red
            { 2, false },
            { 3, false },
            { 4, false }
        });

        // Create controller with lanes 1-4
        var controller = new TrafficLightController(
            sensorIngester,
            timingEngine,
            hardwareController,
            baseDurations,
            new[] { 1, 2, 3, 4 });

        // Start the controller
        controller.Start();

        // Simulate vehicle arrivals (in a real system, this would come from sensors)
        var random = new Random();
        var timer = new System.Timers.Timer(5000); // Check every 5 seconds
        timer.Elapsed += (sender, e) =>
        {
            int lane = random.Next(1, 5);
            int newVehicles = random.Next(0, 10);
            sensorIngester.UpdateLaneQueues(lane, newVehicles);
            Console.WriteLine($"Simulated {newVehicles} vehicles on lane {lane}");
        };
        timer.AutoReset = true;
        timer.Start();

        Console.WriteLine("Traffic light system started. Press any key to exit...");
        Console.ReadKey();
    }
}
```

## Key Features of This Implementation:

1. **Modular Design**:
   - Three distinct interfaces (`IVehicleSensorIngester`, `IAdaptiveTimingEngine`, `IHardwareSignalController`)
   - Each component has a concrete implementation
   - The `TrafficLightController` coordinates between them

2. **Vehicle Sensor Ingester**:
   - Tracks vehicle counts per lane
   - Thread-safe operations with locking
   - Provides current queue data

3. **Adaptive Timing Optimization Engine**:
   - Calculates green durations based on queue lengths
   - Uses a heuristic (1 second per 5 vehicles)
   - Maintains minimum and maximum durations
   - Thread-safe operations

4. **Hardware Signal Controller**:
   - Simulates physical light control
   - Includes async operations for realistic hardware delays
   - Thread-safe state management

5. **Main Controller**:
   - Coordinates between all components
   - Implements a simple control loop
   - Can be extended with more sophisticated logic

## Potential Enhancements:

1. More sophisticated lane selection algorithm (prioritizing higher queues)
2. Yellow light timing based on queue lengths
3. Pedestrian crossing integration
4. Real-time sensor data integration
5. Machine learning for more adaptive timing
6. Fault tolerance and recovery mechanisms

This implementation provides a solid foundation that can be extended based on specific requirements for your traffic light system.
